package br.com.peladaleague.app;
import android.app.AlertDialog;
import android.text.InputType;
import android.widget.*;
import java.util.*;

/** Validating forms keep the dialog open on invalid input. */
final class Forms extends Screen {
    Forms(MainActivity a){super(a);}
    LinearLayout form(){LinearLayout f=Ui.col(a);f.setPadding(Ui.dp(a,20),Ui.dp(a,10),Ui.dp(a,20),Ui.dp(a,12));return f;}
    EditText field(LinearLayout f,String label,String initial,boolean number){Ui.put(f,text(label,12,Ui.MUTED,true),10);EditText e=Ui.input(a,label);if(number)e.setInputType(InputType.TYPE_CLASS_NUMBER);e.setText(initial);e.setMinHeight(Ui.dp(a,48));Ui.put(f,e,6);return e;}
    Spinner spinner(LinearLayout f,String label,List<String> options){Ui.put(f,text(label,12,Ui.MUTED,true),12);Spinner s=new Spinner(a);ArrayAdapter<String> adapter=new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,options);s.setAdapter(adapter);s.setMinimumHeight(Ui.dp(a,48));Ui.put(f,s,4);return s;}
    void dialog(String title,LinearLayout form,String positive,Runnable save){ScrollView sc=new ScrollView(a);sc.addView(form);AlertDialog d=new AlertDialog.Builder(a).setTitle(title).setView(sc).setNegativeButton("Cancelar",null).setPositiveButton(positive,null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{save.run();d.dismiss();}catch(NumberFormatException ex){a.toast("Informe um número válido.");}catch(IllegalArgumentException|IllegalStateException ex){a.toast(ex.getMessage());}}));d.show();}
    void createGroup(){LinearLayout f=form();EditText n=field(f,"Nome da pelada","",false),l=field(f,"Local","",false),s=field(f,"Dia e horário","",false);dialog("Criar pelada",f,"Criar",()->{if(n.getText().toString().trim().length()<3||l.getText().toString().trim().isEmpty()||s.getText().toString().trim().isEmpty())throw new IllegalArgumentException("Preencha nome, local, dia e horário.");long id=db.addGroup(n.getText().toString().trim(),l.getText().toString().trim(),s.getText().toString().trim());db.addMember(id,a.playerId);a.selectGroup(id);});}
    void capacity(){LinearLayout f=form();EditText cap=field(f,"Vagas (2 a 100)",""+db.capacity(a.groupId),true);dialog("Capacidade da sessão",f,"Salvar",()->{db.setCapacity(a.groupId,Integer.parseInt(cap.getText().toString()));a.refresh();});}
    void member(){new AlertDialog.Builder(a).setTitle("Adicionar jogador").setItems(new String[]{"Cadastrar novo jogador local","Usar jogador já cadastrado"},(d,i)->{if(i==0)newPlayer();else{Set<Long> existing=new HashSet<>();for(DemoDb.Player p:db.groupPlayers(a.groupId))existing.add(p.id);List<DemoDb.Player> people=new ArrayList<>();for(DemoDb.Player p:db.players())if(!existing.contains(p.id))people.add(p);if(people.isEmpty()){a.toast("Todos os jogadores cadastrados já estão no grupo.");return;}new AlertDialog.Builder(a).setTitle("Jogadores disponíveis").setItems(people.stream().map(p->p.name).toArray(String[]::new),(di,index)->{db.addMember(a.groupId,people.get(index).id);a.refresh();}).show();}}).show();}
    private void newPlayer(){LinearLayout f=form();EditText n=field(f,"Nome","",false);Spinner pos=spinner(f,"Posição",List.of("GOL","ZAG","MEI","ATA","LIN"));dialog("Novo jogador local",f,"Adicionar",()->{if(n.getText().toString().trim().length()<2)throw new IllegalArgumentException("Informe o nome do jogador.");db.addPlayer(n.getText().toString(),pos.getSelectedItem().toString(),a.groupId);a.refresh();});}
    void editPlayer(DemoDb.Player p){LinearLayout f=form();EditText n=field(f,"Nome",p.name,false),skill=field(f,"Habilidade (1 a 100)",""+p.skill,true);List<String> positions=List.of("GOL","ZAG","MEI","ATA","LIN");Spinner pos=spinner(f,"Posição",positions);pos.setSelection(Math.max(0,positions.indexOf(p.pos)));EditText number=p.id==a.playerId?field(f,"Número da camisa (0 a 99)",""+a.shirtNumber,true):null;dialog("Editar jogador",f,"Salvar",()->{int jersey=number==null?0:Integer.parseInt(number.getText().toString());if(jersey<0||jersey>99)throw new IllegalArgumentException("Número da camisa entre 0 e 99.");db.updatePlayer(p.id,n.getText().toString(),pos.getSelectedItem().toString(),Integer.parseInt(skill.getText().toString()));if(number!=null){a.shirtNumber=jersey;a.getPreferences(0).edit().putInt("shirt",jersey).apply();}a.refresh();});}
}
